<?php $page_title='Dashboard'; require_once 'includes/header.php'; require_login();
$uid=(int)user()['id'];$role=user()['role'];
$myDonations=[];$myRequests=[];$incoming=[];
if($role==='donor'||$role==='admin'){$s=$pdo->prepare("SELECT * FROM food_donations WHERE donor_id=? ORDER BY created_at DESC");$s->execute([$uid]);$myDonations=$s->fetchAll();$s=$pdo->prepare("SELECT r.*,f.title,u.name requester_name FROM food_requests r JOIN food_donations f ON f.id=r.food_id JOIN users u ON u.id=r.requester_id WHERE f.donor_id=? ORDER BY r.created_at DESC");$s->execute([$uid]);$incoming=$s->fetchAll();}
$s=$pdo->prepare("SELECT r.*,f.title,f.location,u.name donor_name FROM food_requests r JOIN food_donations f ON f.id=r.food_id JOIN users u ON u.id=f.donor_id WHERE r.requester_id=? ORDER BY r.created_at DESC");$s->execute([$uid]);$myRequests=$s->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='cancel_request'){$s=$pdo->prepare("UPDATE food_requests SET status='cancelled' WHERE id=? AND requester_id=? AND status='pending'");$s->execute([$id,$uid]);flash('success','Request cancelled.');redirect('dashboard.php');}if($action==='update_request'){$status=$_POST['status']??'pending';if(in_array($status,['accepted','rejected'])){$s=$pdo->prepare("UPDATE food_requests r JOIN food_donations f ON f.id=r.food_id SET r.status=? WHERE r.id=? AND f.donor_id=?");$s->execute([$status,$id,$uid]);$n=$pdo->prepare("SELECT requester_id,food_id FROM food_requests WHERE id=?");$n->execute([$id]);$rq=$n->fetch();if($rq)notify_user((int)$rq['requester_id'],'Food request '.ucfirst($status),'Your request has been '. $status .'.','dashboard.php');flash('success','Request updated.');redirect('dashboard.php');}}}
?>
