<div class="stat-row stat-row-4"><div class="stat-card stat-gradient"><span>My donations</span><strong><?= count($myDonations) ?></strong><small>Listings created</small></div><div class="stat-card"><span>Food shared</span><strong><?= $totalFood ?></strong><small>Servings / units listed</small></div><div class="stat-card"><span>Requests received</span><strong><?= count($incoming) ?></strong><small>Community demand</small></div><div class="stat-card"><span>Requests accepted</span><strong><?= $accepted ?></strong><small>Successful connections</small></div></div>
