<?php if($myDonations): ?><section class="dashboard-section"><div class="section-heading"><div><span class="kicker">DONOR ACTIVITY</span><h2>My food listings</h2></div></div><div class="table-wrap"><table><thead><tr><th>Food</th><th>Quantity</th><th>Location</th><th>Status</th><th>Posted</th></tr></thead><tbody><?php foreach($myDonations as $d): ?><tr><td><b><?= e($d['title']) ?></b><small><?= e($d['category']) ?></small></td><td><?= (int)$d['quantity'] ?> <?= e($d['unit']) ?></td><td><?= e($d['location']) ?></td><td><span class="badge <?= badge_class($d['status']) ?>"><?= e($d['status']) ?></span></td><td><?= e(date('d M Y',strtotime($d['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
<?php if($incoming): ?><section class="dashboard-section"><div class="section-heading"><div><span class="kicker">DONOR REQUESTS</span><h2>People requesting your food</h2></div></div><div class="request-list"><?php foreach($incoming as $r): ?><div class="request-item"><div><b><?= e($r['requester_name']) ?></b><span><?= (int)$r['quantity'] ?> units · <?= e($r['title']) ?></span><p><?= e($r['message'] ?: 'No message added.') ?></p></div><div class="request-actions"><span class="badge <?= badge_class($r['status']) ?>"><?= e($r['status']) ?></span><?php if($r['status']==='pending'): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_request"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="status" value="accepted"><button class="mini-btn">Accept</button></form><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="update_request"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="status" value="rejected"><button class="mini-btn danger">Reject</button></form><?php endif; ?></div></div><?php endforeach; ?></div></section><?php endif; ?>
<section class="dashboard-section"><div class="section-heading"><div><span class="kicker">REQUEST HISTORY</span><h2>My requests</h2></div></div><?php if($myRequests): ?><div class="table-wrap"><table><thead><tr><th>Food</th><th>Donor</th><th>Qty</th><th>Status</th><th>Location</th><th></th></tr></thead><tbody><?php foreach($myRequests as $r): ?><tr><td><b><?= e($r['title']) ?></b></td><td><?= e($r['donor_name']) ?></td><td><?= (int)$r['quantity'] ?></td><td><span class="badge <?= badge_class($r['status']) ?>"><?= e($r['status']) ?></span></td><td><?= e($r['location']) ?></td><td><?php if($r['status']==='pending'): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="cancel_request"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="mini-btn danger">Cancel</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><h3>No requests yet</h3><a class="btn primary" href="food.php">Find food</a></div><?php endif; ?></section>
